  let pivot = dqsTurnOf(a, length(a[0].xyz));
  var real = vec4f(0.0);
  var dual = vec4f(0.0);
  var scale = 0.0;
  for (var i = 0; i < 4; i++) {
    let s = length(bones[i][0].xyz);
    let turn = dqsTurnOf(bones[i], s);
    let side = select(w[i], -w[i], dot(turn, pivot) < 0.0);
    real += turn * side;
    dual += 0.5 * dqsProduct(vec4f(bones[i][3].xyz, 0.0), turn) * side;
    scale += s * w[i];
  }
